<script lang="ts">
 import '../shop-refresh.css';
 import { SlidersHorizontal, Search } from 'lucide-svelte'; import { products } from '../lib/data/products'; import { route, navigate } from '../lib/stores/router'; import ProductCard from '../lib/components/ProductCard.svelte'; import ShopFilters from '../lib/components/ShopFilters.svelte';
 const params = $derived(new URLSearchParams($route.split('?')[1] || '')); let search = $state(''); let category = $state(''); let color = $state(''); let size = $state(''); let maxPrice = $state(5000); let saleOnly = $state(false); let filtersOpen = $state(false);
 $effect(() => { search = params.get('q') || ''; category = params.get('category') || ''; saleOnly = params.get('edit') === 'sale'; });
 let filtered = $derived.by(() => { let list = products.filter(p => (!category || p.category === category) && (!color || p.color === color) && (!size || p.sizes.includes(size)) && p.price <= maxPrice && (!saleOnly || !!p.originalPrice) && (params.get('edit') !== 'new' || p.badge === 'New') && `${p.name} ${p.category} ${p.color} ${p.fabric}`.toLowerCase().includes(search.toLowerCase().trim())); return list; });
 function reset() { search='';category='';color='';size='';maxPrice=5000;saleOnly=false; if(params.get('edit')) navigate('/shop'); }
</script>
<section class="shop-layout shop-page"><div class="mobile-filter-bar"><button class="button outline filter-toggle" aria-expanded={filtersOpen} onclick={() => filtersOpen = !filtersOpen}><SlidersHorizontal size={16}/> Filters</button></div><ShopFilters bind:search bind:category bind:color bind:size bind:maxPrice bind:saleOnly bind:filtersOpen filteredCount={filtered.length} {reset}/><div class="shop-results"><div class="product-grid shop-products">{#each filtered as product}<ProductCard {product}/>{/each}</div>{#if !filtered.length}<div class="empty-state"><Search size={36}/><h2>No pieces in this edit.</h2><p>Try a different colour, collection, or price range.</p><button class="button dark" onclick={reset}>Clear filters</button></div>{/if}</div></section>
